/** Source: berry_tag_screen.c → Task_HandleInput */
export const Task_HandleInput: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  if (!rt.gPaletteFade.active)
      {
          let arrowKeys = JOY_REPEAT(DPAD_ANY);
          if (arrowKeys == DPAD_UP)
              TryChangeDisplayedBerry(taskId, -1);
          else if (arrowKeys == DPAD_DOWN)
              TryChangeDisplayedBerry(taskId, 1);
          else if (JOY_NEW(A_BUTTON | B_BUTTON))
              PrepareToCloseBerryTagScreen(taskId);
      }
};

